const url = 'https://federation.ccdi.cancer.gov/api/v1/subject-diagnosis?search=neuroblastoma&page=1&per_page=1';
try {
  const res = await fetch(url);
  const text = await res.text();
  nodeRepl.write(JSON.stringify({ok: res.ok, status: res.status, headers: Object.fromEntries(res.headers.entries()), text: text.slice(0, 12000)}, null, 2));
} catch (err) {
  nodeRepl.write(JSON.stringify({ok:false, error:String(err), stack: err && err.stack ? String(err.stack).split('\n').slice(0,3).join('\n') : null}, null, 2));
}

